/* episode bar */
function bar(){
  var box=document.getElementById("ep-btns"); box.innerHTML="";
  for(var i=1;i<=NEP;i++){(function(i){var b=el("button","ep-btn",String(i)); b.type="button"; var t=i<=read?"Серия "+i+": "+EPS[i]:"Серия "+i; b.title=t; b.setAttribute("aria-pressed",String(i===read)); b.setAttribute("aria-label",t); b.onclick=function(){setRead(i)}; box.appendChild(b)})(i)}
  document.getElementById("ep-name").textContent="«"+EPS[read]+"»";
  var nt=document.getElementById("ep-note"); if(nt){nt.hidden=read<=DONE; nt.textContent="улики с "+(DONE+1)+"-й серии ещё собираем"}
  var cur=box.children[read-1]; if(cur&&box.scrollWidth>box.clientWidth) box.scrollLeft=cur.offsetLeft-box.clientWidth/2+cur.offsetWidth/2;
}
